import math
import sys
import hashlib
import argon2
import scrypt
import gmpy2

class Hexa():
    def __init__(self):
        pass

    def convert_str(self, data:str) -> str:
        characters:list[int] = []
        processed_data:str = ""
        
        for char in data:
            characters.append(ord(char))
        
        for char in characters:
            processed_data += str(hex(char))
        
        return processed_data

    def convert_int(self, data:int) -> str:
        return hex(data)

    def decode_int(self, hex_value:str) -> int:
        return int(hex_value, 16)

class Process():
    def __init__(self):
        self.N = 2 ** 14
        self.r = 8
        self.p = 1

    def proc(self, password:str, salt:bytes) -> str:
        hashed_password = password.encode()
        hashed_password = argon2.low_level.hash_secret(bytes(hashed_password), salt, 8, 1024 * 1024 * 8, 32, 128, argon2.low_level.Type.ID).hex() + scrypt.hash(hashed_password, salt, N=self.N, r=self.r, p=self.p).hex() + hashlib.sha256(hashed_password).hexdigest() + hashlib.sha3_256(bytes(hashed_password)).hexdigest() + hashlib.sha512(bytes(hashed_password)).hexdigest() + hashlib.sha3_512(bytes(hashed_password)).hexdigest()
        return hashed_password

    def preprocess(self, password:str) -> tuple[str, str]:
        salt = b"GUNgH/[}1hi5Nc&xZ.]L%(X!mqa2&N4QS0u1.}A&;D::YtaD%4.w}H+5(,X$8rv!@yJ*0w_2-%*amgp4tyQXbN*YdCn??}S-NrF,/e3?)9Z=.9kNi@q{Mt@?_0R.F_)U"
        hashed_password = self.proc(password, salt)
        
        return bytes(hashed_password.encode('utf-8')).hex(), salt.hex()

class Prime():
    def __init__(self):
        pass

    def is_prime(self, n:int) -> bool:
        """Check if a number is prime."""
        n = gmpy2.mpz(str(n))
        return gmpy2.is_prime(n)

    def mine_prime(self, n:int) -> int:
        for i in range(n + 1):
            if self.is_prime(n - i):
                return n - i

sys.set_int_max_str_digits(2_000_000_000)

