def hash_value(data:str, prime_number:int, salt:str) -> int:
    """Used to hash some data"""

    while len(data) < 1024:
        data += "\0"
    
    if not prime.is_prime(prime_number):
        raise ValueError("Invalid Prime Number input")
    
    rhash:int = 1
    
    for i, char in enumerate(data):
        rhash *= (ord(char) * prime_number * rhash + i) % (2 ** 1024)
        rhash += int(math.sqrt(2) * prime_number)
        rhash += int(math.pi / math.sqrt(math.e)) * prime_number
        rhash += int(math.sin(math.tan(math.cos(math.e / (math.pi * math.sqrt(math.pi - math.e)) + int(math.tanh(math.sin(prime_number) + math.radians(prime_number / math.pi * math.e))) * prime_number)))) * 1000
