def hash_data(data:str) -> str:
    """Uses the hashing algorithm and generates a hash value"""
    prime_number = prime.mine_prime(1_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000_000)
    data, salt = process.preprocess(data)
    
    rhash:str = str(hexa.convert_int(hash_value(data, prime_number, salt)))[2:]
    
    for i in range(iterations):
        rhash = str(hexa.convert_int(hash_value(rhash, prime_number, salt)))[2:]

    while len(rhash) < 1024:
        rhash = "0" + rhash
    
    return rhash[:1024]

def verify(data:str, hash:str) -> bool:
    """Verify hash"""
    return hash_data(data) == hash


